// News-image entry for 18 November 2026 (Node 22, standard library only).
//
// The picture below is the image itself, stored as base64 text inside this
// file. At run time the program decodes it and writes it to the output
// folder as entry.png. That keeps both runs byte-identical by construction:
// no date, no random value and no network call is involved anywhere.
//
// The picture is a one-page newspaper summary of Wednesday 18 November 2026:
// 20 stories on one page — six big lead stories (Xi meets Putin in Shenzhen,
// the Crimean Bridge arch falls, five tankers sunk in the Gulf, Democrats
// take the Senate, COP31, and Gaza's truce on the brink) plus 14 briefs in
// large type under two section heads, with a date check.
//
// Run it outside the grader with:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// The 1024x1024 PNG, base64-encoded, in a single long line. It was drawn with a
// small script for this day's news and is reproduced here verbatim, so the
// program needs no image file beside it and no drawing library at all.
const PNG_BASE64 = "";

const outputDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
mkdirSync(outputDir, { recursive: true });

writeFileSync(
  join(outputDir, "entry.png"),
  Buffer.from(PNG_BASE64, "base64"),
);
